import os
import sqlite3
from pathlib import Path
from typing import Annotated, Literal
from fastapi import FastAPI, Request, Depends, Query, Header
from fastapi.exceptions import RequestValidationError
from fastapi.responses import JSONResponse, StreamingResponse
from starlette.background import BackgroundTask
from pydantic import BaseModel, ConfigDict, Field
from .database import connect, initialize
from . import certificates as service


class ExportQuery(BaseModel):
    model_config = ConfigDict(extra='forbid')
    q: str = Field(default='', max_length=200)
    sort: Literal['learner_name','course_title','serial_number','issue_date','status'] = 'issue_date'
    order: Literal['asc','desc'] = 'desc'


class ListQuery(ExportQuery):
    page: int = Field(default=1, ge=1)
    page_size: int = Field(default=20, ge=1, le=100)


class IssueRequest(BaseModel):
    model_config = ConfigDict(extra='forbid')
    course_id: int = Field(strict=True, gt=0)


def create_app(db_path=None):
    path = str(db_path or os.environ.get('DB_PATH','data/demo.sqlite3'))
    initialize(path)
    app = FastAPI(title='Certificate Admin Console')
    app.state.db_path = path

    @app.middleware('http')
    async def no_cache(request, call_next):
        response = await call_next(request)
        response.headers['Cache-Control'] = 'no-store'
        return response

    @app.exception_handler(service.DomainError)
    async def domain_error(request, exc):
        return JSONResponse({'error':{'code':exc.code,'message':exc.message}},status_code=exc.status)

    @app.exception_handler(RequestValidationError)
    async def validation_error(request, exc):
        return JSONResponse({'error':{'code':'INVALID_REQUEST','message':'Invalid request parameters or body.'}},status_code=422)

    @app.exception_handler(sqlite3.OperationalError)
    async def database_error(request, exc):
        locked = 'locked' in str(exc).lower() or 'busy' in str(exc).lower()
        return JSONResponse({'error':{'code':'DATABASE_BUSY' if locked else 'INTERNAL_ERROR','message':'Please retry with the same operation key.' if locked else 'The operation could not be completed.'}},status_code=503 if locked else 500,headers={'Retry-After':'1'} if locked else {})

    @app.exception_handler(Exception)
    async def internal_error(request, exc):
        return JSONResponse({'error':{'code':'INTERNAL_ERROR','message':'The operation could not be completed.'}},status_code=500)

    def actor(request: Request):
        return service.actor_for(path,request.headers.get('Authorization'))

    def no_query(request: Request):
        if request.query_params:
            raise service.DomainError(422,'INVALID_REQUEST','This endpoint does not accept query parameters.')

    @app.get('/api/demo-actors', dependencies=[Depends(no_query)])
    def demo_actors():
        db = connect(path)
        try:
            return {'items':[dict(r) for r in db.execute('SELECT a.id,a.email,a.token AS demo_token,t.name AS tenant_name,t.timezone FROM actors a JOIN tenants t ON t.id=a.tenant_id ORDER BY a.id')]}
        finally:
            db.close()

    @app.get('/api/courses', dependencies=[Depends(no_query)])
    def courses(current=Depends(actor)):
        db = connect(path)
        try:
            return {'items':[dict(r) for r in db.execute('SELECT c.id,c.title,COALESCE(SUM(e.completed=1),0) AS completed_count,COALESCE(SUM(e.completed=0),0) AS incomplete_count FROM courses c LEFT JOIN enrollments e ON e.tenant_id=c.tenant_id AND e.course_id=c.id WHERE c.tenant_id=? GROUP BY c.id ORDER BY c.id',(current.tenant_id,))]}
        finally:
            db.close()

    @app.get('/api/certificates')
    def certificates(query: Annotated[ListQuery,Query()], current=Depends(actor)):
        return service.list_certificates(path,current,query)

    @app.get('/api/certificates/export.csv')
    def export(query: Annotated[ExportQuery,Query()], current=Depends(actor)):
        stream = service.CsvExport(path,current,query)
        return StreamingResponse(stream.chunks(),media_type='text/csv; charset=utf-8',headers={'Content-Disposition':'attachment; filename="certificates.csv"'},background=BackgroundTask(stream.close))

    @app.get('/api/certificates/{certificate_id}',  dependencies=[Depends(no_query)])
    def certificate_detail(certificate_id: int, current=Depends(actor)):
        return service.detail(path,current,certificate_id)

    @app.post('/api/certificate-issuances', dependencies=[Depends(no_query)])
    def issue(body: IssueRequest, idempotency_key: Annotated[str, Header(min_length=1,max_length=128,pattern=r'^[A-Za-z0-9_.-]+$')], current=Depends(actor)):
        return service.issue_course(path,current,body.course_id,idempotency_key)

    @app.post('/api/certificates/{certificate_id}/revoke', dependencies=[Depends(no_query)])
    async def revoke(certificate_id: int, request: Request, current=Depends(actor)):
        if await request.body():
            raise service.DomainError(422,'INVALID_REQUEST','Revocation does not accept a body.')
        from starlette.concurrency import run_in_threadpool
        return await run_in_threadpool(service.revoke,path,current,certificate_id)

    dist=Path(__file__).resolve().parent.parent/'frontend'/'dist'
    if dist.exists():
        from fastapi.staticfiles import StaticFiles
        app.mount('/',StaticFiles(directory=dist,html=True),name='console')
    return app
from dataclasses import dataclass
from .database import connect, local_time


class DomainError(Exception):
    def __init__(self, status, code, message):
        self.status, self.code, self.message = status, code, message


@dataclass(frozen=True)
class Actor:
    id: int
    tenant_id: int
    email: str
    timezone: str


def actor_for(path, authorization):
    db = connect(path)
    try:
        token = authorization[7:] if authorization and authorization.startswith('Bearer ') else ''
        row = db.execute('SELECT a.*, t.timezone FROM actors a JOIN tenants t ON t.id=a.tenant_id WHERE a.token=?',(token,)).fetchone()
        if not row:
            raise DomainError(401,'UNAUTHORIZED','A valid demo actor token is required.')
        return Actor(row['id'],row['tenant_id'],row['email'],row['timezone'])
    finally:
        db.close()


SELECT = '''SELECT c.*, l.name AS learner_name, co.title AS course_title FROM certificates c
JOIN learners l ON l.id=c.learner_id AND l.tenant_id=c.tenant_id
JOIN courses co ON co.id=c.course_id AND co.tenant_id=c.tenant_id'''
SORTS = {'learner_name':'l.name COLLATE BINARY','course_title':'co.title COLLATE BINARY','serial_number':'c.serial_number COLLATE BINARY','issue_date':'c.issue_date_local','status':'c.status'}


def query_sql(actor, query):
    q = query.q.strip().casefold().replace('\\','\\\\').replace('%','\\%').replace('_','\\_')
    where = " WHERE c.tenant_id=? AND (l.search_name LIKE ? ESCAPE '\\' OR lower(c.serial_number) LIKE ? ESCAPE '\\')"
    params = (actor.tenant_id, '%' + q + '%', '%' + q + '%')
    order = f' ORDER BY {SORTS[query.sort]} {query.order.upper()}, c.id ASC'
    return where, params, order


def certificate_dict(row, actor):
    data = dict(row)
    data.pop('tenant_id', None)
    data['issued_at_local'] = local_time(data['issued_at'],actor.timezone).isoformat()
    return data


def list_certificates(path, actor, query):
    db = connect(path)
    try:
        db.execute('BEGIN')
        where, params, order = query_sql(actor,query)
        total = db.execute('SELECT count(*) FROM (' + SELECT + where + ')', params).fetchone()[0]
        rows = db.execute(SELECT + where + order + ' LIMIT ? OFFSET ?',(*params,query.page_size,(query.page-1)*query.page_size)).fetchall()
        return {'items':[certificate_dict(r,actor) for r in rows], 'total':total,'page':query.page,'page_size':query.page_size}
    finally:
        db.close()


def detail(path, actor, certificate_id):
    db = connect(path)
    try:
        db.execute('BEGIN')
        row = db.execute(SELECT + ' WHERE c.tenant_id=? AND c.id=?',(actor.tenant_id,certificate_id)).fetchone()
        if not row:
            raise DomainError(404,'NOT_FOUND','Certificate not found.')
        result = certificate_dict(row,actor)
        result['audit_events'] = [dict(r) for r in db.execute('SELECT e.id,e.event_type,a.email AS actor_email,e.created_at FROM audit_events e JOIN actors a ON a.id=e.actor_id AND a.tenant_id=e.tenant_id WHERE e.tenant_id=? AND e.certificate_id=? ORDER BY e.id',(actor.tenant_id,certificate_id))]
        return result
    finally:
        db.close()


class IssuanceRejected(Exception):
    """An explicitly classified learner-local rejection."""


def create_certificate(db, actor, course_id, learner_id, stamp):
    import uuid
    serial = 'CERT-' + uuid.uuid4().hex.upper()
    row = db.execute('INSERT INTO certificates(tenant_id,course_id,learner_id,serial_number,issued_at,issue_date_local,status) VALUES(?,?,?,?,?,?,?)', (actor.tenant_id,course_id,learner_id,serial,stamp,local_time(stamp,actor.timezone).date().isoformat(),'ACTIVE'))
    return row.lastrowid


def issue_course(path, actor, course_id, key, clock=None):
    import hashlib
    import json
    import uuid
    from .database import utc_now
    fingerprint = hashlib.sha256(json.dumps({'version':1,'course_id':course_id},sort_keys=True,separators=(',',':')).encode()).hexdigest()
    db = connect(path)
    try:
        if not db.execute('SELECT 1 FROM courses WHERE tenant_id=? AND id=?',(actor.tenant_id,course_id)).fetchone():
            raise DomainError(404,'NOT_FOUND','Course not found.')
        db.execute('BEGIN IMMEDIATE')
        if not db.execute('SELECT 1 FROM courses WHERE tenant_id=? AND id=?',(actor.tenant_id,course_id)).fetchone():
            raise DomainError(404,'NOT_FOUND','Course not found.')
        old = db.execute('SELECT fingerprint,result_json FROM issuance_operations WHERE tenant_id=? AND actor_id=? AND idempotency_key=?',(actor.tenant_id,actor.id,key)).fetchone()
        if old:
            if old['fingerprint'] != fingerprint:
                raise DomainError(409,'IDEMPOTENCY_CONFLICT','This key was already used for a different request.')
            db.commit()
            return json.loads(old['result_json'])
        stamp = (clock or utc_now)()
        rows = db.execute('SELECT e.learner_id,e.completed,l.name,c.id AS certificate_id FROM enrollments e JOIN learners l ON l.tenant_id=e.tenant_id AND l.id=e.learner_id LEFT JOIN certificates c ON c.tenant_id=e.tenant_id AND c.course_id=e.course_id AND c.learner_id=e.learner_id WHERE e.tenant_id=? AND e.course_id=? ORDER BY e.learner_id',(actor.tenant_id,course_id)).fetchall()
        result = {'operation_id':str(uuid.uuid4()),'course_id':course_id,'status':'COMPLETED','summary':{'issued':0,'skipped':0,'failed':0},'outcomes':[]}
        for row in rows:
            item = {'learner_id':row['learner_id'],'learner_name':row['name'],'outcome':'skipped','reason':None,'certificate_id':None}
            if not row['completed']:
                item['reason'] = 'INCOMPLETE'
            elif row['certificate_id']:
                item['reason'] = 'ALREADY_CERTIFIED'
                item['certificate_id'] = row['certificate_id']
            else:
                db.execute('SAVEPOINT learner')
                try:
                    cid = create_certificate(db,actor,course_id,row['learner_id'],stamp)
                except IssuanceRejected:
                    db.execute('ROLLBACK TO learner')
                    db.execute('RELEASE learner')
                    item.update(outcome='failed',reason='ISSUANCE_REJECTED')
                else:
                    # Audit errors deliberately escape: the entire operation must roll back.
                    db.execute('INSERT INTO audit_events(tenant_id,certificate_id,actor_id,event_type,created_at) VALUES(?,?,?,?,?)',(actor.tenant_id,cid,actor.id,'ISSUED',stamp))
                    db.execute('RELEASE learner')
                    item.update(outcome='issued',certificate_id=cid)
            result['outcomes'].append(item)
            result['summary'][item['outcome']] += 1
        db.execute('INSERT INTO issuance_operations VALUES(?,?,?,?,?,?,?)',(result['operation_id'],actor.tenant_id,actor.id,key,fingerprint,json.dumps(result),stamp))
        db.commit()
        return result
    except BaseException:
        db.rollback()
        raise
    finally:
        db.close()


def revoke(path, actor, certificate_id, clock=None):
    from .database import utc_now
    db = connect(path)
    try:
        db.execute('BEGIN IMMEDIATE')
        row = db.execute('SELECT status FROM certificates WHERE tenant_id=? AND id=?',(actor.tenant_id,certificate_id)).fetchone()
        if not row:
            raise DomainError(404,'NOT_FOUND','Certificate not found.')
        if row['status'] == 'ACTIVE':
            stamp = (clock or utc_now)()
            db.execute("UPDATE certificates SET status='REVOKED',revoked_at=? WHERE tenant_id=? AND id=?",(stamp,actor.tenant_id,certificate_id))
            db.execute('INSERT INTO audit_events(tenant_id,certificate_id,actor_id,event_type,created_at) VALUES(?,?,?,?,?)',(actor.tenant_id,certificate_id,actor.id,'REVOKED',stamp))
        db.commit()
    except BaseException:
        db.rollback()
        raise
    finally:
        db.close()
    return detail(path,actor,certificate_id)


class CsvExport:
    """Owns one sequentially consumed snapshot across handler and stream threads."""
    def __init__(self,path,actor,query):
        self.db = connect(path)
        self.closed = False
        try:
            self.db.execute('BEGIN')
            where,params,order = query_sql(actor,query)
            self.cursor = self.db.execute(SELECT + where + order, params)
            self.first = self.cursor.fetchmany(1000)
        except BaseException:
            self.close()
            raise

    def close(self):
        if not self.closed:
            self.closed=True
            self.db.close()

    def chunks(self):
        import csv
        import io
        output = io.StringIO(newline='')
        writer = csv.writer(output)
        fields = ['learner_name','course_title','serial_number','issue_date_local']
        try:
            writer.writerow(fields)
            yield output.getvalue().encode('utf-8')
            batch = self.first
            while batch:
                output.seek(0)
                output.truncate(0)
                writer.writerows([[row[field] for field in fields] for row in batch])
                yield output.getvalue().encode('utf-8')
                batch=self.cursor.fetchmany(1000)
        finally:
            self.close()
import sqlite3
from pathlib import Path
from datetime import datetime, timezone
from zoneinfo import ZoneInfo


def utc_now():
    return datetime.now(timezone.utc).isoformat(timespec='microseconds').replace('+00:00', 'Z')


def local_time(value, zone):
    return datetime.fromisoformat(value.replace('Z', '+00:00')).astimezone(ZoneInfo(zone))


def connect(path):
    db = sqlite3.connect(path, timeout=10, isolation_level=None, check_same_thread=False)
    db.row_factory = sqlite3.Row
    db.execute('PRAGMA foreign_keys=ON')
    db.execute('PRAGMA busy_timeout=10000')
    return db


SCHEMA = '''
CREATE TABLE IF NOT EXISTS tenants(id INTEGER PRIMARY KEY, name TEXT NOT NULL, timezone TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS actors(id INTEGER PRIMARY KEY, tenant_id INTEGER NOT NULL REFERENCES tenants(id), email TEXT NOT NULL UNIQUE, token TEXT NOT NULL UNIQUE, UNIQUE(tenant_id,id));
CREATE TABLE IF NOT EXISTS courses(id INTEGER PRIMARY KEY, tenant_id INTEGER NOT NULL REFERENCES tenants(id), title TEXT NOT NULL, UNIQUE(tenant_id,id));
CREATE TABLE IF NOT EXISTS learners(id INTEGER PRIMARY KEY, tenant_id INTEGER NOT NULL REFERENCES tenants(id), name TEXT NOT NULL, search_name TEXT NOT NULL, UNIQUE(tenant_id,id));
CREATE TABLE IF NOT EXISTS enrollments(tenant_id INTEGER NOT NULL, course_id INTEGER NOT NULL, learner_id INTEGER NOT NULL, completed INTEGER NOT NULL CHECK(completed IN(0,1)), PRIMARY KEY(tenant_id,course_id,learner_id), FOREIGN KEY(tenant_id,course_id) REFERENCES courses(tenant_id,id), FOREIGN KEY(tenant_id,learner_id) REFERENCES learners(tenant_id,id));
CREATE TABLE IF NOT EXISTS certificates(id INTEGER PRIMARY KEY, tenant_id INTEGER NOT NULL, course_id INTEGER NOT NULL, learner_id INTEGER NOT NULL, serial_number TEXT NOT NULL UNIQUE, issued_at TEXT NOT NULL, issue_date_local TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN('ACTIVE','REVOKED')), revoked_at TEXT, UNIQUE(tenant_id,id), UNIQUE(tenant_id,course_id,learner_id), FOREIGN KEY(tenant_id,course_id) REFERENCES courses(tenant_id,id), FOREIGN KEY(tenant_id,learner_id) REFERENCES learners(tenant_id,id), CHECK((status='ACTIVE' AND revoked_at IS NULL) OR (status='REVOKED' AND revoked_at IS NOT NULL)));
CREATE TABLE IF NOT EXISTS issuance_operations(id TEXT PRIMARY KEY, tenant_id INTEGER NOT NULL, actor_id INTEGER NOT NULL, idempotency_key TEXT NOT NULL, fingerprint TEXT NOT NULL, result_json TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(tenant_id,actor_id,idempotency_key), FOREIGN KEY(tenant_id,actor_id) REFERENCES actors(tenant_id,id));
CREATE TABLE IF NOT EXISTS audit_events(id INTEGER PRIMARY KEY, tenant_id INTEGER NOT NULL, certificate_id INTEGER NOT NULL, actor_id INTEGER NOT NULL, event_type TEXT NOT NULL CHECK(event_type IN('ISSUED','REVOKED')), created_at TEXT NOT NULL, UNIQUE(tenant_id,certificate_id,event_type), FOREIGN KEY(tenant_id,certificate_id) REFERENCES certificates(tenant_id,id), FOREIGN KEY(tenant_id,actor_id) REFERENCES actors(tenant_id,id));
CREATE INDEX IF NOT EXISTS cert_date ON certificates(tenant_id,issue_date_local,id);
CREATE INDEX IF NOT EXISTS cert_serial ON certificates(tenant_id,serial_number,id);
CREATE INDEX IF NOT EXISTS cert_status ON certificates(tenant_id,status,id);
CREATE INDEX IF NOT EXISTS learner_name ON learners(tenant_id,name,id);
'''


def initialize(path):
    Path(path).parent.mkdir(parents=True, exist_ok=True)
    db = connect(path)
    try:
        db.execute('PRAGMA journal_mode=WAL')
        db.executescript(SCHEMA)
        db.execute('BEGIN IMMEDIATE')
        if db.execute('SELECT 1 FROM tenants WHERE id=1').fetchone():
            db.commit()
            return
        db.executemany('INSERT INTO tenants VALUES(?,?,?)', [(1,'East','Australia/Sydney'),(2,'West','Australia/Perth')])
        db.executemany('INSERT INTO actors VALUES(?,?,?,?)', [(1,1,'alice@east.test','east-demo-token'),(2,2,'bob@west.test','west-demo-token')])
        db.executemany('INSERT INTO courses VALUES(?,?,?)', [(1,1,'Safety 101'),(2,2,'Safety 101'),(3,1,'First Aid'),(4,1,'Date Ordering')])
        people = [(1,1,'Alex Lee'),(2,1,'Casey Morgan'),(3,1,'Jordan Chen'),(4,2,'Alex Lee'),(5,2,'Casey Morgan'),(6,2,'Jordan Chen'),(7,1,'Date Later'),(8,1,'Date Earlier')]
        db.executemany('INSERT INTO learners VALUES(?,?,?,?)', [(i,t,n,n.casefold()) for i,t,n in people])
